// IQDI brand asset rules (TEST ONLY project). The SVG masters in assets/branding/ are generated by
// tools/branding/generate_brand.py; these tests pin the owner's refinement decisions and the
// safety rules (real vectors, no embedded raster, no scripts, no official-endorsement wording).
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { contrastRatio, tokens } from '../packages/ui/src/tokens.ts';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const brand = path.join(root, 'assets', 'branding');
const read = (f: string) => readFileSync(path.join(brand, f), 'utf8');
const MASTERS = ['iqdi-logo-original.svg', 'iqdi-logo-dark.svg', 'iqdi-mark-original.svg', 'iqdi-mark-dark.svg', 'iqdi-mark-monochrome.svg', 'iqdi-logo-monochrome.svg', 'iqdi-icon-small.svg', 'iqdi-app-icon.svg'];
const pathData = (svg: string) => [...svg.matchAll(/\sd="([^"]+)"/g)].map((m) => m[1]);
const pngSize = (file: string) => { const b = readFileSync(file); return b.readUInt32BE(0) === 0x89504e47 ? { w: b.readUInt32BE(16), h: b.readUInt32BE(20) } : null; };
const LION = 'M2 30 C6 20 14 12 26 10';

describe('IQDI brand masters are real, safe vectors', () => {
  it.each(MASTERS)('%s: SVG root with viewBox and <title>, no raster, no script, no live text, bounded size', (file) => {
    const svg = read(file);
    expect(svg).toMatch(/<svg xmlns="http:\/\/www\.w3\.org\/2000\/svg" viewBox="[\d. ]+"/);
    expect(svg).toMatch(/<title id="[^"]+">IQDI — Iraqi Digital Identity[^<]*TEST ONLY/);
    expect(svg).not.toMatch(/<image|data:image\/(png|jpe?g|webp)|base64,/i); // not a raster wrapped in SVG
    expect(svg).not.toMatch(/<script|\son[a-z]+=|javascript:|xlink:href="http|href="http/i);
    expect(svg).not.toMatch(/<text[\s>]/); // all lettering converted to outlines
    expect(svg.length).toBeLessThan(90_000);
    expect(pathData(svg).length).toBeLessThan(160); // hand-built geometry, not a thousand-path auto-trace
  });

  it('carries no wording that implies government endorsement', () => {
    for (const file of [...MASTERS, '../../apps/wallet-web/public/manifest.webmanifest']) {
      const text = read(file);
      expect(text).not.toMatch(/وزارة|جمهورية العراق|Ministry|Republic of Iraq|Government of Iraq|official/i);
    }
  });

  it('Original and Dark share one geometry (same paths in the same order); only paint differs', () => {
    expect(pathData(read('iqdi-mark-dark.svg'))).toEqual(pathData(read('iqdi-mark-original.svg')));
    expect(pathData(read('iqdi-logo-dark.svg'))).toEqual(pathData(read('iqdi-logo-original.svg')));
    expect(read('iqdi-mark-dark.svg')).not.toEqual(read('iqdi-mark-original.svg'));
  });

  it('the Dark variant is its own treatment, not just another background', () => {
    const dark = read('iqdi-mark-dark.svg');
    // night-navy trunk, brighter gold, and two different river tones so the rivers stay separate
    expect(dark).toContain('#183766');
    expect(dark).toContain('#F5DC8E');
    expect(dark).toMatch(/iqdi-dark-river1[^>]*><stop offset="0" stop-color="#4A8BE3"/);
    expect(dark).toMatch(/iqdi-dark-river2[^>]*><stop offset="0" stop-color="#3471CD"/);
    expect(dark).not.toMatch(/#000000|fill="black"/i);
  });

  it('full mark: exactly one lion, exactly two rivers, two date clusters', () => {
    for (const file of ['iqdi-mark-original.svg', 'iqdi-logo-dark.svg', 'iqdi-mark-monochrome.svg']) {
      const svg = read(file);
      expect(svg.split(LION).length - 1).toBe(1);
      expect(svg.split('M446 446 C600 446 640 596 800 598').length - 1).toBeGreaterThanOrEqual(1);
      expect(svg.split('M446 560 C600 560 640 712 800 714').length - 1).toBeGreaterThanOrEqual(1);
      expect(svg).not.toMatch(/M446 6\d\d C600/); // no third river band
    }
    const mark = read('iqdi-mark-original.svg');
    expect(mark.match(/<ellipse /g)?.length).toBe(38); // 2 clusters × 19 dates
  });

  it('small icon and app icon: palm + arch + two rivers only (no lion, no tiles, no text, no gradient)', () => {
    for (const file of ['iqdi-icon-small.svg', 'iqdi-app-icon.svg']) {
      const svg = read(file);
      expect(svg).not.toContain(LION);
      expect(svg).not.toMatch(/<pattern|Gradient|<ellipse/);
      expect(svg.match(/C67 \d+ 70 \d+ 89\.5/g)?.length).toBe(2);
    }
  });

  it('monochrome masters use one colour (currentColor) with knock-outs, no gradients', () => {
    for (const file of ['iqdi-mark-monochrome.svg', 'iqdi-logo-monochrome.svg']) {
      const svg = read(file);
      expect(svg).toContain('fill="currentColor"');
      expect(svg).not.toMatch(/Gradient|<pattern|#[0-9a-f]{6}/i);
    }
  });
});

describe('IQDI derived rasters and app icons', () => {
  it('every PNG derivative has the size its name states (width) and the master aspect ratio', () => {
    const dir = path.join(brand, 'png');
    const files = readdirSync(dir).filter((f) => f.endsWith('.png'));
    expect(files.length).toBeGreaterThanOrEqual(30);
    for (const f of files) {
      const m = /-(\d+)\.png$/.exec(f);
      const s = pngSize(path.join(dir, f));
      expect(s?.w, f).toBe(Number(m?.[1]));
      const ratio = f.includes('logo') ? 1372 / 1040 : f.includes('mark') ? 810 / 1040 : 1;
      expect(Math.abs((s?.h ?? 0) - Math.round((s?.w ?? 0) * ratio)), f).toBeLessThanOrEqual(1);
    }
  });

  it('wallet manifest icons exist at their declared sizes and both apps ship the SVG favicon', () => {
    const manifest = JSON.parse(readFileSync(path.join(root, 'apps/wallet-web/public/manifest.webmanifest'), 'utf8')) as { icons: { src: string; sizes: string; purpose: string }[]; theme_color: string };
    expect(manifest.theme_color).toBe(tokens.brand.navy);
    for (const icon of manifest.icons) {
      const s = pngSize(path.join(root, 'apps/wallet-web/public', icon.src));
      expect(`${s?.w}x${s?.h}`).toBe(icon.sizes);
    }
    for (const app of ['wallet-web', 'verifier-web']) {
      expect(readFileSync(path.join(root, 'apps', app, 'public/favicon.svg'), 'utf8')).toBe(read('iqdi-app-icon.svg'));
      expect(pngSize(path.join(root, 'apps', app, 'public/favicon-32.png'))).toEqual({ w: 32, h: 32 });
      expect(readFileSync(path.join(root, 'apps', app, 'index.html'), 'utf8')).not.toMatch(/rel="icon" href="data:/);
    }
    expect(existsSync(path.join(root, 'apps/wallet-web/public/sw.js'))).toBe(false); // still no service worker
  });
});

describe('IQDI brand tokens', () => {
  it('text pairs meet WCAG AA; gold is restricted to artwork and large text on light backgrounds', () => {
    const b = tokens.brand;
    expect(contrastRatio(b.navy, b.ivory)).toBeGreaterThanOrEqual(7);
    expect(contrastRatio(b.blue, b.ivory)).toBeGreaterThanOrEqual(4.5);
    expect(contrastRatio(b.goldOnDark, b.night)).toBeGreaterThanOrEqual(7);
    expect(contrastRatio(b.gold, b.ivory)).toBeLessThan(3); // documented: never small gold text on ivory
  });
});
